k = input(7, "K Neighbors", 1, 20, 1)
lookbackFeatures = input(20, "Feature Window", 5, 40, 1)
historyWindow = input(200, "History Window", 50, 500, 10)
marginThreshold = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
agreementThreshold = input(0.65, "Agreement Threshold", 0.1, 1.0, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

pctNow = 0.0
if bar_index > 0 {
    prevC = close[1]
    if prevC != 0 {
        pctNow := (close - prevC) / abs(prevC) * 100
    }
}

varip pctHist = array(0)
varip closeHist = array(0)
array.push(pctHist, pctNow)
array.push(closeHist, close)

M = 0.0
A = 0.0
D = 1.0
C = 0.0

nBars = array.size(pctHist)
enough = bar_index >= lookbackFeatures + 2 and nBars > lookbackFeatures + 2
if enough {
    // Current feature vector F0 stats (z-normalize basis)
    sum0 = 0.0
    e = 0
    while e < lookbackFeatures {
        sum0 := sum0 + pctHist[nBars - 1 - e]
        e := e + 1
    }
    mean0 = sum0 / lookbackFeatures
    var0 = 0.0
    e = 0
    while e < lookbackFeatures {
        dev0 = pctHist[nBars - 1 - e] - mean0
        var0 := var0 + dev0 * dev0
        e := e + 1
    }
    std0 = sqrt(var0 / lookbackFeatures)
    if std0 < 0.000001 {
        std0 := 0.000001
    }

    // k smallest distances + labels + weights
    bestDist = array()
    bestLab = array()
    bestW = array()
    q = 0
    while q < k {
        array.push(bestDist, 999999.0)
        array.push(bestLab, 0)
        array.push(bestW, 0.0)
        q := q + 1
    }

    startJ = nBars - 1 - historyWindow
    if startJ < lookbackFeatures {
        startJ := lookbackFeatures
    }
    endJ = nBars - 1 - 1
    if endJ > nBars - 2 {
        endJ := nBars - 2
    }

    j = startJ
    while j <= endJ {
        // Fi stats ending at j
        sumF = 0.0
        f = 0
        while f < lookbackFeatures {
            sumF := sumF + pctHist[j - f]
            f := f + 1
        }
        meanF = sumF / lookbackFeatures
        varF = 0.0
        f = 0
        while f < lookbackFeatures {
            devF = pctHist[j - f] - meanF
            varF := varF + devF * devF
            f := f + 1
        }
        stdF = sqrt(varF / lookbackFeatures)
        if stdF < 0.000001 {
            stdF := 0.000001
        }
        // Euclidean distance on z-normalized vectors
        ss = 0.0
        f = 0
        while f < lookbackFeatures {
            z0 = (pctHist[nBars - 1 - f] - mean0) / std0
            zf = (pctHist[j - f] - meanF) / stdF
            dd = z0 - zf
            ss := ss + dd * dd
            f := f + 1
        }
        dist = sqrt(ss)
        lab = 0 - 1
        if closeHist[j + 1] > closeHist[j] {
            lab := 1
        }
        w = 1.0 / (1.0 + dist)
        // sorted insert into top-k
        ins = 0 - 1
        m = 0
        while m < k {
            if dist < bestDist[m] {
                ins := m
                m := k
            }
            m := m + 1
        }
        if ins >= 0 {
            m = k - 1
            while m > ins {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestLab, m, bestLab[m - 1])
                array.set(bestW, m, bestW[m - 1])
                m := m - 1
            }
            array.set(bestDist, ins, dist)
            array.set(bestLab, ins, lab)
            array.set(bestW, ins, w)
        }
        j := j + 1
    }

    bulls = 0
    bears = 0
    wSum = 0.0
    wVote = 0.0
    m = 0
    while m < k {
        if bestDist[m] < 999999.0 {
            if bestLab[m] == 1 {
                bulls := bulls + 1
            } else {
                bears := bears + 1
            }
            wSum := wSum + bestW[m]
            wVote := wVote + bestW[m] * bestLab[m]
        }
        m := m + 1
    }
    M := (bulls - bears) / k
    C := abs(M)
    D := 1.0 - C
    if wSum > 0.000001 {
        A := abs(wVote / wSum)
    } else {
        A := 0.0
    }
}

buyCond = M > 0 and M >= marginThreshold and A >= agreementThreshold
sellCond = M < 0 and abs(M) >= marginThreshold and A >= agreementThreshold
buyPrev = buyCond[1]
sellPrev = sellCond[1]
buySig = buyCond and not buyPrev and bar_index >= lookbackFeatures + 2
sellSig = sellCond and not sellPrev and bar_index >= lookbackFeatures + 2

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "separate")
}

marginChan = M * 100 + close * 0.0
agreeChan = A * 100 + close * 0.0
plot(marginChan, "Vote Margin M x100", "#22cc88", 2, "separate")
plot(agreeChan, "Weighted Agreement A x100", "#ffd43b", 1, "separate")
hline(43, "#22cc88", "separate")
hline(0 - 43, "#ff4477", "separate")
hline(65, "#ffd43b", "separate")

plot3d(marginChan, "Vote Margin Height", "bars3d", "#22cc88", "separate")
plot3d(agreeChan, "Agreement Depth", "ribbon", "#ffd43b", "separate", 1)

// Visible Session Value Terrain POC Model
// Volume-profile-at-price over the visible session: POC + value-area expansion,
// price-leaving-value signals, 2D levels + 3D terrain with labelled POC rail.

numBins = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
sessLen = input(120, "Session Length", 24, 300, 4)
showBox = input(true, "Show Value Area Box")
showRail = input(true, "Show POC Rail")
enable3D = input(true, "Enable 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range ─────────────────────────────
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 { rng := close * 0.01 }

// ─── Persistent bins (zeroed and rebuilt every bar) ────
var binVol = array()
var binInit = 0
if binInit == 0 {
    i0 = 0
    while i0 < 48 {
        array.push(binVol, 0.0)
        i0 := i0 + 1
    }
    binInit := 1
}

// Zero active bins
i = 0
while i < numBins {
    array.set(binVol, i, 0.0)
    i := i + 1
}

// Deposit each bar in session into bin of its typical price
k = 0
while k < sessLen {
    hk = high[k]
    lk = low[k]
    ck = close[k]
    vk = volume[k]
    typ = (hk + lk + ck) / 3
    b = floor((typ - ll) / rng * numBins)
    if b < 0 { b := 0 }
    if b > numBins - 1 { b := numBins - 1 }
    array.set(binVol, b, array.get(binVol, b) + vk)
    k := k + 1
}

// ─── Totals + point of control ─────────────────────────
totalVol = array.sum(binVol)
pocBin = 0
pocVal = array.get(binVol, 0)
j = 1
while j < numBins {
    v = array.get(binVol, j)
    if v > pocVal {
        pocVal := v
        pocBin := j
    }
    j := j + 1
}
pocPrice = ll + (pocBin + 0.5) / numBins * rng
pocShare = 0.0
if totalVol > 0 { pocShare := pocVal / totalVol * 100 }

// ─── Value area: expand from POC ───────────────────────
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < numBins {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(binVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < numBins - 1 { rightVal := array.get(binVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < numBins - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) / numBins * rng
valPrice = ll + vaLow / numBins * rng
vaWidthPct = (vahPrice - valPrice) / rng * 100
insideVA = close >= valPrice and close <= vahPrice
prevInside = insideVA[1]
wasIn = prevInside
if bar_index == 0 { wasIn := true }

// ─── Terrain helpers (vary every bar) ──────────────────
aboveVol = 0.0
belowVol = 0.0
m = 0
while m < numBins {
    vv = array.get(binVol, m)
    if m > pocBin { aboveVol := aboveVol + vv }
    if m < pocBin { belowVol := belowVol + vv }
    m := m + 1
}
terrainH = pocShare + vaWidthPct * 0.05
plateauH = 0.0
if totalVol > 0 { plateauH := accum / totalVol * 100 }
terrainCol = "#22cc88"
if not insideVA { terrainCol := "#ff8800" }

// ─── Signals: price leaving value (edge only) ──────────
buySig = wasIn and not insideVA and close > vahPrice and close[1] <= vahPrice
sellSig = wasIn and not insideVA and close < valPrice and close[1] >= valPrice
if bar_index == 0 {
    buySig := false
    sellSig := false
}

if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }
if buySig { plotshape_3d(bar_index, vahPrice, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "separate") }
if sellSig { plotshape_3d(bar_index, valPrice, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "separate") }

// ─── 2D: same POC/VAH/VAL values as 3D ─────────────────
plot(close, "Price", "#ffffff", 1)
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(pocShare, "POC Share", "#ffd43b", 1, "separate")
plot(plateauH, "VA Fill %", "#22cc88", 1, "separate")

if showBox { box.new(bar_index - sessLen, vahPrice, bar_index, valPrice, "#22cc88", "rgba(34,204,136,0.08)", 1, "VABox") }
if showRail { text.new(bar_index, pocPrice, "POC", "#ffd43b", 1, "POCLabel") }

// ─── 3D: value terrain + labelled POC rail ─────────────
if enable3D { plot3d(terrainH, "Value Terrain", "surface", terrainCol, "separate", 0) }
if enable3D { plot3d(pocShare, "POC Rail", "line3d", "#ffd43b", "separate", 2) }

var lastPocBin = -1
if pocBin != lastPocBin {
    if enable3D { label3d(bar_index, pocShare, "POC", "#ffd43b", 1.0, 2, "separate") }
}
lastPocBin := pocBin

if not insideVA { bgcolor("rgba(255,136,0,0.05)") }

// FIX 1 - frozen var: var lvl = highest(high, 20) ran once on bar 0 -> plain assignment recomputed every bar.
// FIX 2 - future leak: close[-1] reads a not-yet-formed bar -> use close on the current bar.
// FIX 3 - Pine signature: plotshape(true, low, "Buy", shape.triangleup, color.green) -> OakScript plotshape(bar_index, price, title, style, color).
// FIX 4 - wrong pane: oscillator RSI in pane="3d" is a spiky forest over candles -> pane="separate" per PANE LAW.
lvlLen = input(20, "Level Length", 1, 100, 1)
rsiLen = input(14, "RSI Length", 1, 100, 1)
lvl = highest(high, lvlLen)
r = rsi(close, rsiLen)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1)
plot3d(r, "RSI", "surface", "#b48cff", "separate")

flowBase = input(80, "Flow PSI Base", 0, 300, 1)
critThresh = input(150, "Critical Threshold", 50, 300, 1)
spinFactor = input(1.0, "Spin Factor", 0.1, 5.0, 0.1)
ringCount = input(3, "Ring Count", 1, 5, 1)
ringExp = input(1.0, "Ring Expansion Rate", 0.1, 5.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

var discAngle = 0.0
var ringRad = 0.0

flowPsi = flowBase + (close - open) * 3 + (high - low) * 2
velocity = flowPsi * spinFactor
locked = flowPsi > critThresh
critMod = critThresh + (close - open) * 0.05

if locked {
  discAngle := discAngle[1]
} else {
  discAngle := discAngle[1] + velocity
}

if locked {
  ringRad := ringRad[1] + ringExp * ringCount
} else {
  ringRad := 0.0
}

spinPulse = discAngle - discAngle[1]
discVal = flowPsi + spinPulse * 0.2
ringVal = critMod + ringRad * 2 + (flowPsi - critMod) * 0.15
overState = locked

overStart = locked and not locked[1]
overEnd = not locked and locked[1]

if overStart {
  plotshape(bar_index, high, "OVERPRESSURE", "triangledown", "#ff4477")
}

if overEnd {
  plotshape(bar_index, low, "Pressure OK", "triangleup", "#22cc88")
}

if overStart {
  plotshape_3d(bar_index, flowPsi, "Lock", "cube", "#ff4477", markerSize, 2, "separate", 0, discAngle, 0)
}

if overStart {
  label3d(bar_index, flowPsi, "OVERPRESSURE", "#ff4477", 2, 3, "separate")
}

plot(flowPsi, "Flow PSI", "#22cc88", 2)
plot(critMod, "Critical", "#ff4477", 1, "stepline")
plot3d(discVal, "Valve Disc", "torus", "#22cc88", "separate", 0)
plot3d(ringVal, "Shock Rings", "trail", "#ff4477", "separate", 1)
